// NEW proposal only: exact original pixel layers, never floor/collision authority.
const cache=new WeakMap();
export function drawGym4DoorLayer(ctx,image,part,canvasFactory=(w,h)=>new OffscreenCanvas(w,h)){let byPart=cache.get(image);if(!byPart){byPart=new WeakMap();cache.set(image,byPart)}let layer=byPart.get(part);if(!layer){const mask=canvasFactory(image.width,image.height),m=mask.getContext('2d');m.beginPath();part.polygon.forEach(([x,y],i)=>i?m.lineTo(x,y):m.moveTo(x,y));m.closePath();m.fill();const alpha=m.getImageData(0,0,image.width,image.height).data;mask.width=1;mask.height=1;layer=canvasFactory(image.width,image.height);const g=layer.getContext('2d');g.drawImage(image,0,0);const pixels=g.getImageData(0,0,image.width,image.height);for(let i=3;i<pixels.data.length;i+=4)if(alpha[i]<128)pixels.data[i]=0;g.putImageData(pixels,0,0);byPart.set(part,layer)}ctx.drawImage(layer,0,0)}
export function composeGym4DoorDepth(ctx,image,{parts,state,actors,canvasFactory}){for(const actor of [...actors].sort((a,b)=>a.foot[1]-b.foot[1])){actor.draw(ctx);for(const part of parts.filter(p=>p.states.includes(state)&&actor.foot[1]<p.depthY))drawGym4DoorLayer(ctx,image,part,canvasFactory)}}
// Scoped provider API for future integration. Does not own/close original image.
export function createGym4DoorLayerRenderer({image,parts,state,canvasFactory=(w,h)=>new OffscreenCanvas(w,h)}){let disposed=false;const local=[];const release=()=>{for(const{layer}of local){layer.width=1;layer.height=1}local.length=0;const old=cache.get(image);if(old)for(const part of parts){const layer=old.get(part);if(layer){layer.width=1;layer.height=1;old.delete(part)}}cache.delete(image)};try{for(const part of parts.filter(p=>p.states.includes(state))){const layer=canvasFactory(image.width,image.height);local.push({part,layer});drawGym4DoorLayer(layer.getContext('2d'),image,part,canvasFactory)}}catch(error){release();throw error}return Object.freeze({draw(ctx,actors){if(disposed)return;for(const actor of [...actors].sort((a,b)=>a.foot[1]-b.foot[1])){actor.draw(ctx);for(const{part,layer}of local)if(actor.foot[1]<part.depthY)ctx.drawImage(layer,0,0)}},dispose(){if(disposed)return;disposed=true;release()}})}
